#[test]
fn the_classification_matches_the_binary64_reimplementation_bit_for_bit() {
    // SD-J1.
    let mut sets = 0;
    let mut counts = [0usize; 4];
    let mut layout = Vec::new();
    let mut values = Vec::new();
    let mut expected = Vec::new();
    let mut scales: Vec<(u32, Kind, u64)> = Vec::new();
    let mut extents = Vec::new();
    for line in VECTORS.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        match f[0] {
            "set" => {
                layout.clear();
                values.clear();
                expected.clear();
                scales.clear();
                extents = f[3..].iter().map(|h| hex(h)).collect();
            }
            "row" => {
                layout.push(QuantityMeta {
                    id: QuantityId::Displacement(Dof::from_global(layout.len())),
                    kind: Kind::ALL[f[1].parse::<usize>().unwrap()],
                    body: f[2].parse().unwrap(),
                    input_derived: f[3] == "1",
                });
                values.push(outcome(f[4]));
                expected.push(class(f[5]));
            }
            "scales" => {
                let b: u32 = f[1].parse().unwrap();
                for (k, h) in f[2..].iter().enumerate() {
                    scales.push((b, Kind::ALL[k], u64::from_str_radix(h, 16).unwrap()));
                }
            }
            "end" => {
                let publication = classify_rows(&layout, &values, &extents);
                let got: Vec<RowClass> = publication.rows.iter().map(|r| r.class).collect();
                assert_eq!(got, expected, "set {sets}");
                assert_eq!(publication.body_scales, scales, "set {sets}");
                for c in &got {
                    counts[match c {
                        RowClass::RelativeVerified => 0,
                        RowClass::AbsoluteVerified { .. } => 1,
                        RowClass::InputDerived => 2,
                        RowClass::Unpublishable => 3,
                    }] += 1;
                }
                sets += 1;
            }
            _ => {}
        }
    }
    // 405 sets, and A1's four (ROOT's ruling on RV19-6).
    assert_eq!(sets, 409);
    assert!(counts.iter().all(|&c| c > 50), "{counts:?}");

#[test]
fn amendment_a1_gives_each_row_its_publication_rounding_below_2_to_the_minus_988() {
    // D1 revision 5a.3 amendment A1 (ROOT's ruling on RV19-6): where
    // 0 < S* < 2^-988, b_row = fl↑(fl↑(2^-64·S*) + fl↑(2^-53·|q|) + 2^-1074).
    let s = support::pow2(-995);
    // q = S* (TINY-S-995's scale): 2^-1059 + 2^-1048 + 2^-1074, exact.
    assert_eq!(row_bound(s, s).to_bits(), 0x0000_0000_0400_8001);
    assert_eq!(
        classify(s, s),
        RowClass::AbsoluteVerified {
            bound_bits: 0x0000_0000_0400_8001
        }
    );
    // A zero row: 2^-1059 + 2^-1074.
    assert_eq!(row_bound(0.0, s).to_bits(), 0x8001);
    // It covers the row's own rounding (at most 2^-53·|q| + 2^-1075) beside b.
    for q in [
        s,
        -0.75 * s,
        f64::from_bits(s.to_bits() - 1),
        3.0 * support::pow2(-1060),
    ] {
        let b = row_bound(q, s);
        assert!(
            b > absolute_bound(s) + q.abs() * support::pow2(-53),
            "{q:e}"
        );
    }
    // Just below 2^-988, where 2^-53·|q| is normal: the sum rounded upward
    // once (GEN's value).
    let below = f64::from_bits(0x022F_FFFF_FFFF_FFFF);
    assert_eq!(row_bound(below, below).to_bits(), 0x0000_0002_0040_0001);
    // At 2^-988 and above, and at S* = 0, the plain rule.
    let at = support::pow2(-988);
    assert_eq!(row_bound(0.5 * at, at), absolute_bound(at));
    assert_eq!(row_bound(1.0, 1.0), absolute_bound(1.0));
    assert_eq!(row_bound(0.0, 0.0), 0.0);
}
